window.DDIMG=Object.assign(window.DDIMG||{},{"portrait-clair":"data:image/webp;base64,","portrait-marron":"data:image/webp;base64,","portrait-noir":"data:image/webp;base64,"});
document.addEventListener("DOMContentLoaded",()=>document.querySelectorAll("img[data-img]").forEach(i=>{const s=window.DDIMG[i.dataset.img];if(s)i.src=s}));